"""Independent exact timing/budget arithmetic; final record adapter remains pending."""
from decimal import Decimal
from fractions import Fraction
REPLICATES={'development':8192,'validation':32768}
WRITER_LIMITS={'development':21600,'validation':43200}
VERIFIER_LIMIT=57600
SESSION_LIMIT=295800
INITIAL_FREE=34345762816
PHASE_RAW={'development':1896382464,'validation':7585529856}
PHASE_BOUND={'development':2584248320+8192,'validation':10286661632+8192}
def duration(value):
 assert type(value) in (float,int,Decimal,str),'No boolean or unsupported duration'
 d=Decimal(str(value));assert d.is_finite() and d>=0
 return Fraction(d)
def stage_seconds(repeated,fixed,name):
 assert name in REPLICATES
 return 2*(duration(repeated)*REPLICATES[name]+duration(fixed))
def stage_gate(repeated,fixed,name,kind):
 assert kind in ('writer','primary','reviewer')
 projected=stage_seconds(repeated,fixed,name)
 budget=WRITER_LIMITS[name] if kind=='writer' else VERIFIER_LIMIT
 return {'projected_numerator':projected.numerator,'projected_denominator':projected.denominator,'budget_seconds':budget,'passed':projected<=budget,'legacy12h_passed':projected<=43200,'legacy14h_passed':projected<=50400}
def session_gate(stage_values,extra_seconds):
 assert len(stage_values)==6
 projected=sum(stage_values,Fraction())+2*duration(extra_seconds)
 return {'projected_numerator':projected.numerator,'projected_denominator':projected.denominator,'budget_seconds':SESSION_LIMIT,'passed':projected<=SESSION_LIMIT}
